package world

import (
	"errors"
	"fmt"
)

// ConflictError 表示保存与存档当前状态冲突：槽重名、覆盖所依据的
// 记录已不是该槽最新记录等。调用方应当重新读取后再决定是否重试。
type ConflictError struct {
	Slot   string
	Reason string
}

func (e *ConflictError) Error() string {
	if e.Slot == "" {
		return "world: 存档冲突: " + e.Reason
	}
	return fmt.Sprintf("world: 存档槽 %q 冲突: %s", e.Slot, e.Reason)
}

// NotFoundError 表示指定的槽或记录不存在。
type NotFoundError struct {
	Slot   string
	Record RecordID
}

func (e *NotFoundError) Error() string {
	switch {
	case e.Record != "":
		return fmt.Sprintf("world: 记录不存在: %s", e.Record)
	case e.Slot != "":
		return fmt.Sprintf("world: 存档槽不存在: %q", e.Slot)
	default:
		return "world: 槽或记录不存在"
	}
}

// CorruptError 表示记录内容损坏：校验和不符、父记录链断裂、
// 数据无法解析等。
type CorruptError struct {
	Slot   string
	Record RecordID
	Reason string
}

func (e *CorruptError) Error() string {
	where := e.Slot
	if e.Record != "" {
		if where != "" {
			where += "/"
		}
		where += string(e.Record)
	}
	if where == "" {
		where = "?"
	}
	return fmt.Sprintf("world: 记录损坏(%s): %s", where, e.Reason)
}

// VersionRejectedError 表示记录自身完好，但其规则版本不在调用方
// 明确给出的可接受版本集合内。
type VersionRejectedError struct {
	Slot     string
	Record   RecordID
	Version  string
	Accepted []string
}

func (e *VersionRejectedError) Error() string {
	return fmt.Sprintf("world: 记录 %s 的规则版本 %q 不在可接受版本集合 %v 内",
		e.Record, e.Version, e.Accepted)
}

// ErrUnrecoverable 表示槽中找不到任何一份校验通过且版本可接受的
// 历史记录，无法恢复。调用方可用 errors.Is 判断。
var ErrUnrecoverable = errors.New("world: 没有可恢复的历史记录")

// UnrecoverableError 包装 ErrUnrecoverable 并给出具体原因。
type UnrecoverableError struct {
	Slot   string
	Reason string
}

func (e *UnrecoverableError) Error() string {
	return fmt.Sprintf("world: 槽 %q 不可恢复: %s", e.Slot, e.Reason)
}

func (e *UnrecoverableError) Unwrap() error { return ErrUnrecoverable }

package world_test

import (
	"errors"
	"fmt"
	"log"
	"os"

	"github.com/descikazuyq/world-rules/world"
)

// printContinueState 以固定格式打印一行世界状态，便于对照读档前后的变化。
func printContinueState(tag string, s world.State) {
	c := s.Characters[0]
	fmt.Printf("%s: time=%d %s@%s", tag, s.Time, c.ID, c.Location)
	for _, it := range c.Items {
		fmt.Printf(" %s=%d", it.Item, it.Count)
	}
	fmt.Println()
}

// Example_continueSavedGame 演示读档后在同一存档槽上继续：
// 首次保存（角色已有位置、物品和非零时间片）-> 重新打开存档 ->
// 显式给出可接受规则版本并读回当前记录 -> WorldFromState 承接完整状态 ->
// 内存中 Apply 一次合法移动与物品变化 -> 带读回记录标识 Replace 覆盖回原槽
// -> 分别读取新当前记录与被覆盖的旧记录；并演示版本拒绝与标识过期冲突。
func Example_continueSavedGame() {
	const slot = "adventure"
	acceptedV1 := []string{"v1"}

	// 示例规则：三个地点、两条无向道路、两种物品，hero 携带总量上限 10。
	rules := world.Rules{
		Version:   "v1",
		Locations: []string{"village", "forest", "mine"},
		Edges: []world.Edge{
			{From: "village", To: "forest"},
			{From: "forest", To: "mine"},
		},
		ItemKinds:   []string{"wood", "ore"},
		CarryLimits: map[string]int{"hero": 10},
	}

	dir, err := os.MkdirTemp("", "world-continue-*")
	if err != nil {
		log.Fatal(err)
	}
	defer os.RemoveAll(dir)

	// 1) 准备世界：NewWorld 的时间片固定从 0 开始。
	w0, err := world.NewWorld(world.InitialData{
		Seed:  20240801,
		Rules: rules,
		Characters: []world.Character{{
			ID:       "hero",
			Location: "village",
			Items: []world.CharacterItem{
				{Item: "wood", Count: 2},
				{Item: "ore", Count: 1},
			},
		}},
	})
	if err != nil {
		log.Fatal(err)
	}
	printContinueState("新建", w0.Snapshot())

	// 推进到非零时间片：沿 village-forest 移动并改变物品数量，总量 4 <= 10。
	if _, err := w0.Apply(world.Commit{
		Moves:       []world.Move{{Character: "hero", To: "forest"}},
		ItemChanges: []world.ItemChange{{Character: "hero", Item: "wood", Delta: 1}},
		Time:        4,
	}); err != nil {
		log.Fatal(err)
	}

	// 2) 首次保存：创建命名槽，产生槽首记录；保存时角色已有位置、物品和
	// 非零时间片。
	arch0, err := world.Create(dir)
	if err != nil {
		log.Fatal(err)
	}
	if _, err := arch0.Save(slot, w0); err != nil {
		log.Fatal(err)
	}
	printContinueState("准备", w0.Snapshot())

	// 3) 另一次会话：重新打开这份存档，显式给出可接受的规则版本，读回槽
	// 当前记录。读取不改写存档。
	arch, err := world.Open(dir)
	if err != nil {
		log.Fatal(err)
	}
	rec, err := arch.Latest(slot, acceptedV1)
	if err != nil {
		log.Fatal(err)
	}

	// 读回的记录保留种子、完整规则、角色物品内容与已保存的时间片。
	s := rec.State
	var roads []string
	for _, e := range s.Rules.Edges {
		roads = append(roads, e.From+"-"+e.To)
	}
	fmt.Printf("读档: seed=%d rules=%s time=%d\n", s.Seed, s.Rules.Version, s.Time)
	fmt.Printf("读档: places=%v roads=%v kinds=%v hero上限=%d\n",
		s.Rules.Locations, roads, s.Rules.ItemKinds, s.Rules.CarryLimits["hero"])
	printContinueState("读档", s)

	// 4) 承接完整状态重建可继续的世界：保留时间片 4。继续存档只能用
	// WorldFromState；NewWorld 建立的是时间从零开始的新世界。
	w, err := world.WorldFromState(rec.State)
	if err != nil {
		log.Fatal(err)
	}

	// Commit.Time 是目标绝对时间片，不是增加的步数：3 早于读回的 4，
	// 即使没有任何移动或物品变化也必须失败。
	if _, err := w.Apply(world.Commit{Time: 3}); err != nil {
		fmt.Printf("拒绝时间倒退: %v\n", err)
	}

	// 一次合法的继续：沿 forest-mine 道路移动，ore +2（1->3，总量 6 <= 10），
	// 目标绝对时间片为 7。
	if _, err := w.Apply(world.Commit{
		Moves:       []world.Move{{Character: "hero", To: "mine"}},
		ItemChanges: []world.ItemChange{{Character: "hero", Item: "ore", Delta: 2}},
		Time:        7,
	}); err != nil {
		log.Fatal(err)
	}
	printContinueState("继续", w.Snapshot())

	// Apply 成功只改变内存世界：槽内当前记录仍是覆盖前的内容。
	stored, err := arch.Latest(slot, acceptedV1)
	if err != nil {
		log.Fatal(err)
	}
	printContinueState("存档未变", stored.State)

	// 5) 覆盖回原槽必须带上本次读回的记录标识：成功后得到独立的新标识，
	// 新记录以读回记录为父；first/rec 等旧记录不受影响。
	next, err := arch.Replace(slot, w, rec.ID)
	if err != nil {
		log.Fatal(err)
	}
	fmt.Printf("覆盖: 新标识独立=%t 以读回记录为父=%t\n",
		next.ID != rec.ID, next.Parent == rec.ID)

	cur, err := arch.Latest(slot, acceptedV1)
	if err != nil {
		log.Fatal(err)
	}
	printContinueState("当前", cur.State)

	// 被覆盖的原记录仍可按其标识读取。
	old, err := arch.Record(slot, rec.ID, acceptedV1)
	if err != nil {
		log.Fatal(err)
	}
	printContinueState("旧记录", old.State)

	// 失败条件一：记录规则版本不在可接受集合内 -> 版本拒绝，不能把这份
	// 记录当成新世界继续。
	if _, err := arch.Latest(slot, []string{"v9"}); err != nil {
		var vr *world.VersionRejectedError
		if !errors.As(err, &vr) {
			log.Fatal(err)
		}
		fmt.Printf("版本拒绝: %t 记录版本=%s\n", true, vr.Version)
	}

	// 失败条件二：读回的标识已经过期（槽刚被本次覆盖推进）-> 覆盖报冲突，
	// 已有当前记录保持原样。
	if _, err := arch.Replace(slot, w, rec.ID); err != nil {
		var ce *world.ConflictError
		if !errors.As(err, &ce) {
			log.Fatal(err)
		}
		fmt.Printf("冲突: 过期标识覆盖被拒绝=%t\n", true)
	}
	unchanged, err := arch.Latest(slot, acceptedV1)
	if err != nil {
		log.Fatal(err)
	}
	printContinueState("当前仍在", unchanged.State)

	// 正确后续：重新读取当前记录后再决定。这里在内存世界上再做一次合法
	// 提交（mine->forest，ore -1，目标时间片 9），用重新读回的标识覆盖，
	// 新记录以重读标识为父。
	if _, err := w.Apply(world.Commit{
		Moves:       []world.Move{{Character: "hero", To: "forest"}},
		ItemChanges: []world.ItemChange{{Character: "hero", Item: "ore", Delta: -1}},
		Time:        9,
	}); err != nil {
		log.Fatal(err)
	}
	retried, err := arch.Replace(slot, w, unchanged.ID)
	if err != nil {
		log.Fatal(err)
	}
	fmt.Printf("重读后重试: 父记录为重读标识=%t\n", retried.Parent == unchanged.ID)
	final, err := arch.Latest(slot, acceptedV1)
	if err != nil {
		log.Fatal(err)
	}
	printContinueState("最终", final.State)

	// Output:
	// 新建: time=0 hero@village wood=2 ore=1
	// 准备: time=4 hero@forest wood=3 ore=1
	// 读档: seed=20240801 rules=v1 time=4
	// 读档: places=[village forest mine] roads=[village-forest forest-mine] kinds=[wood ore] hero上限=10
	// 读档: time=4 hero@forest wood=3 ore=1
	// 拒绝时间倒退: world: 时间不能倒退: 当前 4, 提交目标 3
	// 继续: time=7 hero@mine wood=3 ore=3
	// 存档未变: time=4 hero@forest wood=3 ore=1
	// 覆盖: 新标识独立=true 以读回记录为父=true
	// 当前: time=7 hero@mine wood=3 ore=3
	// 旧记录: time=4 hero@forest wood=3 ore=1
	// 版本拒绝: true 记录版本=v1
	// 冲突: 过期标识覆盖被拒绝=true
	// 当前仍在: time=7 hero@mine wood=3 ore=3
	// 重读后重试: 父记录为重读标识=true
	// 最终: time=9 hero@forest wood=3 ore=2
}

package world

import (
	"reflect"
	"testing"
)

// itemOrderRules 是含三个地点、四种物品的规则。四种物品让每个角色都可能
// 获得多个原先没有的新种类，从而区分“按首次出现追加”与“按名称排序”。
func itemOrderRules() Rules {
	return Rules{
		Version:   "v1",
		Locations: []string{"hall", "yard", "cave"},
		Edges: []Edge{
			{From: "hall", To: "yard"},
			{From: "yard", To: "cave"},
		},
		ItemKinds:   []string{"gold", "key", "gem", "orb"},
		CarryLimits: map[string]int{"hero": 30, "mage": 30},
	}
}

// itemOrderWorld 建立两个角色、物品列表刻意不按名称排序且含零数量条目的
// 世界：hero 为 key(1)、gold(0)，mage 为 gem(1)、key(0)。hero 可新增的
// 种类是 orb、gem；mage 可新增的是 orb、gold，两边的新增次序互相独立。
func itemOrderWorld(t *testing.T) *World {
	t.Helper()
	w, err := NewWorld(InitialData{
		Seed:  7,
		Rules: itemOrderRules(),
		Characters: []Character{
			{ID: "hero", Location: "hall", Items: []CharacterItem{
				{Item: "key", Count: 1},
				{Item: "gold", Count: 0},
			}},
			{ID: "mage", Location: "yard", Items: []CharacterItem{
				{Item: "gem", Count: 1},
				{Item: "key", Count: 0},
			}},
		},
	})
	if err != nil {
		t.Fatalf("NewWorld: %v", err)
	}
	return w
}

// wantItems 按 (物品, 数量) 对校验物品列表的完整排列：长度、名称次序与
// 数量都必须逐位相同，不能只比总量。
func wantItems(t *testing.T, got []CharacterItem, want ...CharacterItem) {
	t.Helper()
	if len(got) != len(want) {
		t.Fatalf("物品列表长度不符: 得 %+v，想 %+v", got, want)
	}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("物品列表第 %d 项不符: 得 %+v，想 %+v（完整得 %+v）", i, got[i], want[i], got)
		}
	}
}

// 已有条目保持原位置、未涉及条目原样不动；新增种类只追加一个条目，并按
// 它们在该角色增减条目中首次出现的先后排列（orb 先于 gem，与名称次序
// 相反）；已有物品减到零仍留在原位置；先增后减、最终为零的新物品（orb）
// 也要追加并保留，不得因净变化为零而省略；同一种新增物品（gem）多次出现
// 不得产生重复条目，也不得移到最后一次出现的位置。
func TestApplyItemListOrderAndZeroEntries(t *testing.T) {
	w := itemOrderWorld(t)
	st, err := w.Apply(Commit{
		ItemChanges: []ItemChange{
			{Character: "hero", Item: "key", Delta: 2},  // 已有：1 -> 3，位置不动
			{Character: "hero", Item: "orb", Delta: 1},  // 新种类首次出现（orb 先）
			{Character: "hero", Item: "orb", Delta: -1}, // 先增后减，净 0，仍保留
			{Character: "hero", Item: "gem", Delta: 5},  // 新种类首次出现（gem 后）
			{Character: "hero", Item: "gem", Delta: -2}, // 同一种新增物品重复出现
			{Character: "hero", Item: "gem", Delta: 1},
		},
		Time: 1,
	})
	if err != nil {
		t.Fatalf("合法提交应成功: %v", err)
	}
	hero := findCharacter(t, st, "hero")
	wantItems(t, hero.Items,
		CharacterItem{Item: "key", Count: 3},
		CharacterItem{Item: "gold", Count: 0},
		CharacterItem{Item: "orb", Count: 0},
		CharacterItem{Item: "gem", Count: 4},
	)
	// 返回状态与世界当前快照的数量、排列一致，而不只是总量相同。
	snapHero := findCharacter(t, w.Snapshot(), "hero")
	if !reflect.DeepEqual(hero.Items, snapHero.Items) {
		t.Fatalf("返回状态与世界快照的物品列表不一致: %+v vs %+v", hero.Items, snapHero.Items)
	}
}

// 同一次提交中不同角色的增减条目交错出现且涉及相同物品名称时，每个角色
// 独立承接自己的原列表与新增次序：hero 先见 gem 再见 orb，mage 先见 orb
// 再见 gold（两者都与按名称排序相反，也与跨角色的全局首次出现次序相反）；
// 不能把另一角色的首次出现次序套用过来，角色本身的排列也保持不变。
func TestApplyInterleavedCharactersKeepOwnOrder(t *testing.T) {
	w := itemOrderWorld(t)
	st, err := w.Apply(Commit{
		ItemChanges: []ItemChange{
			{Character: "hero", Item: "gold", Delta: 3}, // hero 已有零条目：0 -> 3
			{Character: "mage", Item: "orb", Delta: 4},  // mage 新种类 1：orb
			{Character: "hero", Item: "gem", Delta: 3},  // hero 新种类 1：gem
			{Character: "mage", Item: "gem", Delta: -1}, // mage 已有：1 -> 0，留在原位
			{Character: "mage", Item: "gold", Delta: 1}, // mage 新种类 2：gold
			{Character: "hero", Item: "orb", Delta: 2},  // hero 新种类 2：orb
			{Character: "hero", Item: "key", Delta: -1}, // hero 已有：1 -> 0，留在原位
			{Character: "mage", Item: "gold", Delta: -1}, // 新物品净变化为 0，仍保留
			{Character: "hero", Item: "gem", Delta: 1},  // 重复出现：不新增条目、不移位
			{Character: "hero", Item: "gem", Delta: -1},
		},
		Time: 2,
	})
	if err != nil {
		t.Fatalf("合法提交应成功: %v", err)
	}
	if len(st.Characters) != 2 || st.Characters[0].ID != "hero" || st.Characters[1].ID != "mage" {
		t.Fatalf("角色排列不应改变: %+v", st.Characters)
	}
	hero := findCharacter(t, st, "hero")
	wantItems(t, hero.Items,
		CharacterItem{Item: "key", Count: 0},
		CharacterItem{Item: "gold", Count: 3},
		CharacterItem{Item: "gem", Count: 3},
		CharacterItem{Item: "orb", Count: 2},
	)
	mage := findCharacter(t, st, "mage")
	wantItems(t, mage.Items,
		CharacterItem{Item: "gem", Count: 0},
		CharacterItem{Item: "key", Count: 0},
		CharacterItem{Item: "orb", Count: 4},
		CharacterItem{Item: "gold", Count: 0},
	)
	snap := w.Snapshot()
	snapHero := findCharacter(t, snap, "hero")
	snapMage := findCharacter(t, snap, "mage")
	if !reflect.DeepEqual(hero.Items, snapHero.Items) || !reflect.DeepEqual(mage.Items, snapMage.Items) {
		t.Fatalf("返回状态与世界快照不一致: hero %+v vs %+v; mage %+v vs %+v",
			hero.Items, snapHero.Items, mage.Items, snapMage.Items)
	}
}

// 最终数量合法的前提下，只改变同一物品增减条目的次序不改变最终数量与
// 列表排列；若同时改变了不同新增种类第一次出现的先后，新增条目的列表
// 次序应随之改变。
func TestApplyDeltaOrderVersusFirstSeenOrder(t *testing.T) {
	// 同一物品的增减条目重排（两个新种类都是 orb 先首次出现）：
	// 数量与排列都不变，且中途暂时为负（gem 先 -1）仍成功。
	first := []ItemChange{
		{Character: "hero", Item: "orb", Delta: 3},
		{Character: "hero", Item: "key", Delta: 3},
		{Character: "hero", Item: "gem", Delta: -1},
		{Character: "hero", Item: "gem", Delta: 3},
	}
	second := []ItemChange{
		{Character: "hero", Item: "orb", Delta: 3},
		{Character: "hero", Item: "gem", Delta: 3},
		{Character: "hero", Item: "key", Delta: 3},
		{Character: "hero", Item: "gem", Delta: -1},
	}
	want := []CharacterItem{
		{Item: "key", Count: 4},
		{Item: "gold", Count: 0},
		{Item: "orb", Count: 3},
		{Item: "gem", Count: 2},
	}
	for i, changes := range [][]ItemChange{first, second} {
		w := itemOrderWorld(t)
		st, err := w.Apply(Commit{ItemChanges: changes, Time: 1})
		if err != nil {
			t.Fatalf("第 %d 个提交应成功: %v", i, err)
		}
		got := findCharacter(t, st, "hero").Items
		if !reflect.DeepEqual(got, want) {
			t.Fatalf("仅重排同一物品增减条目时结果应不变: 得 %+v，想 %+v", got, want)
		}
	}

	// 同样的增减集合，只改变两个新增种类第一次出现的先后（gem 先）：
	// 最终数量不变，但新增条目次序应变为 gem 在前、orb 在后。
	w := itemOrderWorld(t)
	st, err := w.Apply(Commit{ItemChanges: []ItemChange{
		{Character: "hero", Item: "gem", Delta: -1},
		{Character: "hero", Item: "orb", Delta: 3},
		{Character: "hero", Item: "key", Delta: 3},
		{Character: "hero", Item: "gem", Delta: 3},
	}, Time: 1})
	if err != nil {
		t.Fatalf("gem 首次先出现的提交应成功: %v", err)
	}
	wantItems(t, findCharacter(t, st, "hero").Items,
		CharacterItem{Item: "key", Count: 4},
		CharacterItem{Item: "gold", Count: 0},
		CharacterItem{Item: "gem", Count: 2},
		CharacterItem{Item: "orb", Count: 3},
	)
}

// 一次提交同时含合法移动、新增物品和已有物品增减，但某个角色最终数量为
// 负时整次提交失败并返回 *RuleError；同次提交中其他角色也不能留下新条目、
// 归零结果或次序变化，所有角色的位置、物品列表和时间片都保持提交前内容。
func TestApplyNegativeFinalLeavesNoListChange(t *testing.T) {
	w := itemOrderWorld(t)
	before := w.Snapshot()
	_, err := w.Apply(Commit{
		Moves: []Move{{Character: "mage", To: "cave"}},
		ItemChanges: []ItemChange{
			{Character: "hero", Item: "gem", Delta: 4},  // hero 新增合法物品
			{Character: "mage", Item: "gold", Delta: 2}, // mage 新增合法物品
			{Character: "hero", Item: "key", Delta: 1},
			{Character: "mage", Item: "gem", Delta: -2}, // mage: 1 - 2 = -1，非法
		},
		Time: 5,
	})
	mustRuleError(t, err, "mage", "gem", "负")
	after := w.Snapshot()
	if !statesEqual(before, after) {
		t.Fatalf("失败提交留下列表变化: 前 %+v，后 %+v", before.Characters, after.Characters)
	}
	if after.Time != 0 {
		t.Fatalf("时间片不应推进，得到 %d", after.Time)
	}
	// 明确核对其他角色没有留下新条目或归零结果。
	wantItems(t, findCharacter(t, after, "hero").Items,
		CharacterItem{Item: "key", Count: 1},
		CharacterItem{Item: "gold", Count: 0},
	)
	mage := findCharacter(t, after, "mage")
	if mage.Location != "yard" {
		t.Fatalf("mage 的移动也应撤销，得到 %q", mage.Location)
	}
	wantItems(t, mage.Items,
		CharacterItem{Item: "gem", Count: 1},
		CharacterItem{Item: "key", Count: 0},
	)
}

// 同上，但失败原因是某个角色最终携带总量超过上限：其他角色在同次提交中的
// 新条目、数量变化与排列变化同样必须全部撤销。
func TestApplyCarryOverflowLeavesNoListChange(t *testing.T) {
	rules := itemOrderRules()
	rules.CarryLimits = map[string]int{"hero": 10, "mage": 3}
	w, err := NewWorld(InitialData{
		Seed:  7,
		Rules: rules,
		Characters: []Character{
			{ID: "hero", Location: "hall", Items: []CharacterItem{
				{Item: "key", Count: 2},
				{Item: "gold", Count: 0},
			}},
			{ID: "mage", Location: "yard", Items: []CharacterItem{
				{Item: "gem", Count: 1},
				{Item: "key", Count: 0},
			}},
		},
	})
	if err != nil {
		t.Fatalf("NewWorld: %v", err)
	}
	before := w.Snapshot()
	_, err = w.Apply(Commit{
		Moves: []Move{{Character: "hero", To: "yard"}},
		ItemChanges: []ItemChange{
			{Character: "mage", Item: "gold", Delta: 1}, // mage 新条目，最终总量 3，合法
			{Character: "mage", Item: "key", Delta: 1},
			{Character: "hero", Item: "gem", Delta: 11}, // hero 最终: 0+0+11 = 11 > 10
			{Character: "hero", Item: "key", Delta: -2}, // hero 已有条目归零
		},
		Time: 6,
	})
	mustRuleError(t, err, "hero", "上限")
	after := w.Snapshot()
	if !statesEqual(before, after) {
		t.Fatalf("失败提交留下列表变化: 前 %+v，后 %+v", before.Characters, after.Characters)
	}
	if after.Time != 0 {
		t.Fatalf("时间片不应推进，得到 %d", after.Time)
	}
	hero := findCharacter(t, after, "hero")
	if hero.Location != "hall" {
		t.Fatalf("hero 的移动应撤销，得到 %q", hero.Location)
	}
	wantItems(t, hero.Items,
		CharacterItem{Item: "key", Count: 2},
		CharacterItem{Item: "gold", Count: 0},
	)
	wantItems(t, findCharacter(t, after, "mage").Items,
		CharacterItem{Item: "gem", Count: 1},
		CharacterItem{Item: "key", Count: 0},
	)
}

