521		st := w.Snapshot()
522		st.Rules.CarryLimits = map[string]int{"hero": 0}
523		env := &envelope{
524			Format:    archiveFormatVersion,
525			ID:        RecordID("r" + strings.Repeat("cd", 16)),
526			SlotFirst: true,
527			State:     st,
528		}
529		env.Checksum = computeChecksum(env)
530		if err := writeRecord(dir, env); err != nil {
531			t.Fatalf("writeRecord: %v", err)
532		}
533		if err := a.createSlotPointer("slot", env.ID); err != nil {
534			t.Fatalf("createSlotPointer: %v", err)
535		}
536		if _, err := a.RecoverLatest("slot", []string{"v1"}); !errors.Is(err, ErrUnrecoverable) {
537			t.Fatalf("没有可用记录应返回 ErrUnrecoverable，得到 %v", err)
538		}
539		if _, err := a.PreviewRecovery("slot", []string{"v1"}); !errors.Is(err, ErrUnrecoverable) {
540			t.Fatalf("没有可用记录时预览应返回 ErrUnrecoverable，得到 %v", err)
541		}
542	}
543	
544	// 没有上限、各单种数量合法但总量很大的旧存档仍可读取和分支。
545	func TestHugeTotalNoLimitRecordReadable(t *testing.T) {
546		a, _ := newTestArchive(t)
547		w, err := NewWorld(InitialData{
548			Seed:  1,
549			Rules: noLimitRules(),
550			Characters: []Character{
551				{ID: "hero", Location: "hall", Items: []CharacterItem{
552					{Item: "gold", Count: math.MaxInt},
553					{Item: "key", Count: math.MaxInt},
554				}},
555			},
556		})
557		if err != nil {
558			t.Fatalf("NewWorld: %v", err)
559		}
560		info, err := a.Save("slot", w)
561		if err != nil {
562			t.Fatalf("Save: %v", err)
563		}
564		rec, err := a.Latest("slot", []string{"v1"})
565		if err != nil {
566			t.Fatalf("无上限大总量记录应可读取: %v", err)
567		}
568		if rec.State.Characters[0].Items[0].Count != math.MaxInt {
569			t.Fatalf("读取不应修补数量: %+v", rec.State.Characters[0].Items)
570		}
571		if _, err := WorldFromState(rec.State); err != nil {
572			t.Fatalf("无上限大总量状态应可继续: %v", err)
